import{_ as t,c as o,o as r,ah as i}from"./chunks/framework.D6otvB2a.js";const u=JSON.parse('{"title":"Creating Your Project Repository","description":"","frontmatter":{},"headers":[],"relativePath":"github-repository-setup.md","filePath":"github-repository-setup.md","lastUpdated":1787778254000}'),a={name:"github-repository-setup.md"};function s(n,e,c,d,l,p){return r(),o("div",null,e[0]||(e[0]=[i('<h1 id="creating-your-project-repository" tabindex="-1">Creating Your Project Repository <a class="header-anchor" href="#creating-your-project-repository" aria-label="Permalink to &quot;Creating Your Project Repository&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page contains instructions for creating your own personal repository for a project in this course, starting from the project&#39;s starter template on GitHub. You will need to complete these steps <strong>once per project</strong>, before following the <a href="/per-project-setup">Per-Project Setup</a> instructions to clone and start working on it.</p></div><h2 id="what-is-a-github-template-repository" tabindex="-1">What is a GitHub Template Repository? <a class="header-anchor" href="#what-is-a-github-template-repository" aria-label="Permalink to &quot;What is a GitHub Template Repository?&quot;">​</a></h2><p>A template repository is a special kind of GitHub repository that lets you generate a brand new repository with the same starter files, folder structure, and history-free commit as the template, but under your own account. For each project in this course, course staff provide a template repository (e.g.: <code>project-1-starter</code>) containing the starter code, instructions, and configuration you&#39;ll need. Using the template feature ensures you get your own independent, private copy to work in, rather than modifying the shared template directly.</p><h2 id="setup-instructions" tabindex="-1">Setup Instructions <a class="header-anchor" href="#setup-instructions" aria-label="Permalink to &quot;Setup Instructions&quot;">​</a></h2><h3 id="create-a-repository-from-the-template" tabindex="-1">Create a Repository From the Template <a class="header-anchor" href="#create-a-repository-from-the-template" aria-label="Permalink to &quot;Create a Repository From the Template&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Make sure you are signed in to <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> with your own personal account before starting these steps.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>When you get to the <code>Visibility</code> setting below, do <strong>not</strong> select <code>Public</code>! Making your repository public exposes your work to other students (and the internet), which is an academic integrity violation. If you accidentally create a public repository, see the <a href="#common-issues">Common Issues</a> section below to fix it immediately.</p></div><ol><li>Navigate to the starter template repository for the project you are starting (e.g.: <code>https://github.com/CSCI-442-Mines/PROJECT_NAME-starter</code>, where <code>PROJECT_NAME</code> is the name of the project, such as <code>project-1</code>).</li><li>Click the green <code>Use this template</code> button near the top right of the page, then select <code>Create a new repository</code> from the dropdown menu.</li><li>On the <code>Create a new repository</code> page, fill out the following fields: <ul><li><strong>Owner</strong>: select your own personal GitHub account (<strong>not</strong> the <code>CSCI-442-Mines</code> organization). You will not have permission to create repositories directly under the organization.</li><li><strong>Repository name</strong>: name your repository <code>PROJECT_NAME-USERNAME</code>, where <code>PROJECT_NAME</code> is the name of the project (e.g.: <code>project-1</code>) and <code>USERNAME</code> is your GitHub username (e.g.: <code>ghost</code>). For example: <code>project-1-ghost</code>.</li><li><strong>Visibility</strong>: select <code>Private</code>.</li></ul></li><li>Leave the remaining options (such as <code>Include all branches</code>) at their default (unchecked) values.</li><li>Click the green <code>Create repository</code> button and wait for GitHub to finish generating your new repository from the template.</li></ol><h3 id="find-your-repository-url" tabindex="-1">Find Your Repository URL <a class="header-anchor" href="#find-your-repository-url" aria-label="Permalink to &quot;Find Your Repository URL&quot;">​</a></h3><p>Once your repository has been created, you&#39;ll land on its main page. Click the green <code>Code</code> button, and copy either the HTTPS or SSH URL, depending on which authentication method you set up in the <a href="/student-environment#setup-git-inside-the-dev-container">Setup Git Inside the Dev Container</a> section.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep this URL handy! You&#39;ll use it as <code>PROJECT_REPOSITORY_URL</code> when you head over to the <a href="/per-project-setup">Per-Project Setup</a> page for instructions on cloning your repository inside your dev container and getting it ready to work on.</p></div><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="accidentally-created-a-public-repository" tabindex="-1">Accidentally Created a Public Repository <a class="header-anchor" href="#accidentally-created-a-public-repository" aria-label="Permalink to &quot;Accidentally Created a Public Repository&quot;">​</a></h3><ul><li>Symptom: you selected <code>Public</code> instead of <code>Private</code> when creating your repository (or forgot to check the visibility setting).</li><li>Solution: immediately go to your repository&#39;s <code>Settings</code> tab, scroll to the bottom <code>Danger Zone</code> section, and click <code>Change visibility</code> to switch it to <code>Private</code>.</li></ul><h3 id="created-the-repository-under-the-wrong-owner" tabindex="-1">Created the Repository Under the Wrong Owner <a class="header-anchor" href="#created-the-repository-under-the-wrong-owner" aria-label="Permalink to &quot;Created the Repository Under the Wrong Owner&quot;">​</a></h3><ul><li>Symptom: you selected the <code>CSCI-442-Mines</code> organization (or some other account) as the <code>Owner</code> instead of your personal account, and the creation failed or the repository ended up somewhere unexpected.</li><li>Solution: delete the incorrectly created repository (<code>Settings &gt; Danger Zone &gt; Delete this repository</code>) and repeat the <a href="#create-a-repository-from-the-template">Create a Repository From the Template</a> steps, making sure to select your personal account as the <code>Owner</code>.</li></ul><h3 id="cloned-or-forked-the-template-instead-of-using-it" tabindex="-1">Cloned or Forked the Template Instead of Using It <a class="header-anchor" href="#cloned-or-forked-the-template-instead-of-using-it" aria-label="Permalink to &quot;Cloned or Forked the Template Instead of Using It&quot;">​</a></h3><ul><li>Symptom: you ran <code>git clone</code> directly on the template repository&#39;s URL, or used GitHub&#39;s <code>Fork</code> button instead of <code>Use this template</code>, and now your repository is linked to (or a fork of) the shared template repository instead of being an independent copy.</li><li>Solution: delete the repository you created and repeat the <a href="#create-a-repository-from-the-template">Create a Repository From the Template</a> steps, making sure to click the green <code>Use this template</code> button (<strong>not</strong> <code>Fork</code> or the template repository&#39;s own <code>Code</code> button).</li></ul>',19)]))}const y=t(a,[["render",s]]);export{u as __pageData,y as default};
